import { z } from "zod";

/**
 * Single source of truth for what makes a valid student record.
 * Both the manual entry form AND the Excel/CSV importer validate against
 * this same schema, so business rules never drift between the two.
 *
 * Note: admissionNumber (displayed as "Student ID") is deliberately NOT
 * part of this input schema - it's auto-generated by generateStudentId()
 * at insert time in createStudent(), never supplied by the caller.
 */
export const studentSchema = z.object({
  firstName: z.string().trim().min(1, "First name is required").max(100),
  lastName: z.string().trim().min(1, "Last name is required").max(100),

  dateOfBirth: z
    .string()
    .refine((val) => !Number.isNaN(Date.parse(val)), "Invalid date of birth")
    .refine((val) => new Date(val) < new Date(), "Date of birth must be in the past"),

  gender: z.enum(["male", "female", "other"], {
    message: "Gender must be male, female, or other",
  }),

  classId: z.string().uuid("Please select a class"),
  sectionId: z.string().uuid().optional().or(z.literal("")),

  guardianName: z.string().trim().min(1, "Guardian name is required").max(200),
  guardianPhone: z
    .string()
    .trim()
    .min(7, "Enter a valid phone number")
    .max(20),
  guardianEmail: z
    .string()
    .trim()
    .email("Invalid email")
    .optional()
    .or(z.literal("")),
  fatherName: z.string().trim().max(200).optional().or(z.literal("")),
  motherName: z.string().trim().max(200).optional().or(z.literal("")),
  address: z.string().trim().max(500).optional().or(z.literal("")),

  admissionDate: z
    .string()
    .refine((val) => !Number.isNaN(Date.parse(val)), "Invalid admission date"),

  // Raw key/value pairs for spreadsheet columns that didn't map to any
  // known field - not user-entered via the manual form, only ever
  // populated by the importer. Not validated beyond being string pairs;
  // it's a preservation mechanism, not structured business data.
  extraFields: z.record(z.string(), z.string()).optional(),
});

export type StudentFormValues = z.infer<typeof studentSchema>;

// Result shape used consistently for both manual submit and bulk row validation
export type StudentValidationResult =
  | { success: true; data: StudentFormValues }
  | { success: false; errors: Record<string, string> };

export function validateStudent(input: unknown): StudentValidationResult {
  const result = studentSchema.safeParse(input);
  if (result.success) {
    return { success: true, data: result.data };
  }
  const errors: Record<string, string> = {};
  for (const issue of result.error.issues) {
    const field = issue.path.join(".") || "form";
    if (!errors[field]) errors[field] = issue.message;
  }
  return { success: false, errors };
}
